CASES.push({
  id:'c6', no:'CASE 006', level:3, type:'工程', grade:'六年级', minutes:9,
  title:'看不见的工程总量',
  stem:'一项工程，甲队单独做 12 天完成，乙队单独做 18 天完成。两队合作，几天可以完成？',
  tags:['工程问题','单位“1”'],
  independentSay:['他理解了“把总量看作 1”，这一步很多人卡住。','可以追问他：如果甲队中途休息 2 天，答案会怎么变？'],
  steps:[
    {q:'这道题在问什么？', dim:'reading', probe:'读懂问题',
     expect:{label:'合作所需天数', keys:['几天','多少天','合作','完成时间']},
     confuse:[{label:'求各自效率', keys:['每天做多少','效率','几分之几'], reply:'“{hit}”是中间量，不是最终问题。题目问的是：两队<b>合作</b>几天完成。'}],
     idk:'看最后一句：两队合作，几天可以完成？',
     off:'“{hit}”还没回答“几天”。',
     retry:'最后问的是合作完成需要的天数。',
     hint:'问的是天数，不是效率。',
     l4:'我给你半步：要求的是合作完成的天数。',
     tag:'审题', say:['他把中间量当成了问题。','可以让他把最后的问句划出来。']},

    {q:'题目没给工程总量，怎么办？', dim:'model', probe:'单位“1”思想',
     expect:{label:'把总量看作 1', keys:['看作1','设成1','当作1','单位1','总量是1','假设是1']},
     confuse:[{label:'想先求具体工程量', keys:['先求总','多少米','多少吨','具体'], reply:'“{hit}”不需要——题目没给具体量，就把它整体看成 <b>1</b>，效率用分数表示。'}],
     idk:'总量不知道，但我们可以把它当成一个整体。当成几最方便？',
     off:'“{hit}”走不通。总量未知时，通常把它设为 1。',
     retry:'总量没给，就把它整体看作 1。',
     hint:'把整项工程看成 1 份，甲每天做的就是其中的一部分。',
     l4:'我给你半步：把工程总量看作 1。',
     tag:'建模', say:['他没建立“总量为 1”的意识。','可以问他：总量不知道，能不能先当成 1 份？']},

    {q:'那甲队每天完成这项工程的几分之几？', dim:'relation', probe:'效率=1÷时间',
     expect:{label:'1/12', keys:['十二分之一','1/12','12分之1']},
     confuse:[{label:'写成 12', keys:['12'], reply:'“{hit}”是天数，不是效率。12 天做完，每天做的就是 1/12。'}],
     idk:'12 天做完一整项，每天做几分之几？',
     off:'“{hit}”还不是效率。用 1 ÷ 12。',
     retry:'12 天做完，每天完成 1/12。',
     hint:'把 1 平均分成 12 份，取一份。',
     l4:'我给你半步：甲每天完成 1/12。',
     tag:'关系', say:['他把天数当成了效率。','可以问他：12 天做完，一天做完多少？']},

    {q:'两队合作，每天一共完成几分之几？', dim:'calc', probe:'分数相加',
     expect:{label:'5/36', keys:['三十六分之五','5/36','36分之5','七点二分之一']},
     confuse:[{label:'分母相加', keys:['1/30','三十分之一'], reply:'“{hit}”把分母直接相加了。分数相加要先通分：1/12 + 1/18。'}],
     idk:'1/12 + 1/18，先通分到 36。',
     off:'“{hit}”还不对。把两个分数通分后相加。',
     retry:'1/12 + 1/18，通分到 36：3/36 + 2/36。',
     hint:'公分母是 36：1/12 = 3/36，1/18 = 2/36。',
     l4:'我给你半步：3/36 + 2/36 = 5/36。',
     tag:'计算', say:['分数加法时把分母直接相加了。','可以让他先把两个分数都换成 36 分之几。']},

    {q:'每天完成 5/36，那完成整项工程要几天？', dim:'calc', probe:'1÷效率和',
     expect:{label:'7.2 天', keys:['7.2','36/5','七点二','7天多']},
     confuse:[{label:'直接取倒数相加', keys:['5','36','6'], reply:'“{hit}”不对。要算的是 1 里面有几个 5/36，也就是 1 ÷ 5/36。'}],
     idk:'1 ÷ 5/36，就是 36 ÷ 5。',
     off:'“{hit}”还不是天数。用 1 除以 5/36。',
     retry:'1 ÷ 5/36 = 36 ÷ 5。',
     hint:'一天做 5 份，一共 36 份，要几天？',
     l4:'我给你半步：1 ÷ 5/36 = 7.2 天。',
     tag:'计算', say:['他知道用除法，但倒数没取对。','可以问他：一共 36 份，每天做 5 份。']},

    {q:'最后一问：如果甲队中途休息 2 天，完成时间会比 7.2 天长还是短？', dim:'transfer', probe:'迁移：效率变化',
     expect:{label:'更长', keys:['更长','变长','长','增加']},
     confuse:[{label:'认为不变', keys:['不变','一样','还是7.2'], reply:'“{hit}”不对：少一个人干活，同样的工程量当然要更久。'}],
     idk:'少干了两天活，总量没变，时间会怎样？',
     off:'“{hit}”没回答长还是短。',
     retry:'少了一个人干活，时间会变长还是变短？',
     hint:'工程量不变，效率变低了。',
     l4:'我给你半步：效率变低，时间会更长。',
     tag:'迁移', say:['他会套公式，但没把“效率变化”联系起来。','可以问他：活没少，人少干了，时间呢？']}
  ]
});

CASES.push({
  id:'c7', no:'CASE 007', level:3, type:'盈亏', grade:'五年级', minutes:8,
  title:'多了八个，少了六个',
  stem:'老师给学生分苹果。每人分 3 个，多出 8 个；每人分 5 个，少 6 个。一共有多少名学生？',
  tags:['盈亏问题','两次分配'],
  independentSay:['他抓住了“两次分配的差”，这是盈亏问题的核心。','可以追问他：如果每人分 4 个，会多还是少？'],
  steps:[
    {q:'这道题在问什么？', dim:'reading', probe:'读懂问题',
     expect:{label:'学生人数', keys:['多少名','多少人','学生数','几个人']},
     confuse:[{label:'求苹果数', keys:['多少苹果','几个苹果','苹果数'], reply:'“{hit}”不是问题。最后问的是<b>多少名学生</b>。'}],
     idk:'看最后一句：一共有多少名学生？',
     off:'“{hit}”还不是问题。最后问的是人数。',
     retry:'最后一句问的是学生人数。',
     hint:'问的是人，不是苹果。',
     l4:'我给你半步：要求的是学生人数。',
     tag:'审题', say:['他把苹果数当成了问题。','可以让他圈出“多少名学生”。']},

    {q:'两种分法，每人差了几个苹果？', dim:'relation', probe:'分配差',
     expect:{label:'差 2 个', keys:['2个','两个','差2','2']},
     confuse:[{label:'算成总数差', keys:['8','6','14'], reply:'“{hit}”是苹果总数的差。这一步只看<b>每个人</b>：3 个和 5 个差多少？'}],
     idk:'每人 3 个，变成每人 5 个，每人多了几个？',
     off:'“{hit}”不是每人的差。5 − 3。',
     retry:'每人 3 个和每人 5 个，差几个？',
     hint:'只看一个人：从 3 个加到 5 个。',
     l4:'我给你半步：每人差 2 个。',
     tag:'关系', say:['他把“每人差”和“总数差”混了。','可以让他只看一个学生：3 个变 5 个，多几个？']},

    {q:'那苹果总数一共差了多少个？', dim:'relation', probe:'总量差',
     expect:{label:'14 个', keys:['14']},
     confuse:[{label:'相减', keys:['2','8','6'], reply:'“{hit}”不对。第一次多 8 个，第二次少 6 个，一多一少要<b>相加</b>。'}],
     idk:'第一次多 8 个，第二次少 6 个。从多 8 到少 6，中间差多少？',
     off:'“{hit}”还不是总量差。注意“多”和“少”方向相反。',
     retry:'多 8 和少 6，加起来是多少？',
     hint:'从“多 8 个”走到“少 6 个”，一共走了 14 个。',
     l4:'我给你半步：8 + 6 = 14 个。',
     tag:'关系', say:['看到“多”和“少”就直接相减了。','可以画一条数轴：+8 到 −6 有多远。']},

    {q:'每人差 2 个，总数差 14 个。那有多少名学生？', dim:'calc', probe:'总量差÷每人差',
     expect:{label:'7 名', keys:['7']},
     confuse:[{label:'除反了', keys:['28','2','12'], reply:'“{hit}”除错了。要用总数差 14 去除以每人差 2。'}],
     idk:'14 里面有几个 2？',
     off:'“{hit}”还不是人数。14 ÷ 2。',
     retry:'14 ÷ 2，你算算。',
     hint:'每个学生贡献 2 个的差，一共 14 个差。',
     l4:'我给你半步：14 ÷ 2 = 7 名学生。',
     tag:'计算', say:['公式对了，除法算错。','可以让他用 7×2 验算回 14。']},

    {q:'最后一问：如果改成每人分 4 个，苹果会多还是少？', dim:'transfer', probe:'迁移：中间分配',
     expect:{label:'多（会剩）', keys:['多','剩','有剩余','多一点']},
     confuse:[{label:'认为会少', keys:['少','不够'], reply:'“{hit}”再想想：每人 3 个时还多 8 个，加到 4 个，用掉的苹果并没有超过总数。'}],
     idk:'每人 3 个多 8 个，那每人 4 个呢？',
     off:'“{hit}”没回答多还是少。',
     retry:'每人 3 个时多 8 个，加到 4 个会怎样？',
     hint:'7 个学生，每人多 1 个，一共多用 7 个，原来多 8 个。',
     l4:'我给你半步：还会多出 1 个。',
     tag:'迁移', say:['他会套公式，但换个分配数就不会判断了。','可以让他算：每人多 1 个，一共多用几个？']}
  ]
});

CASES.push({
  id:'c8', no:'CASE 008', level:2, type:'年龄', grade:'五年级', minutes:6,
  title:'差几岁不会变',
  stem:'父亲今年 40 岁，儿子今年 12 岁。几年后，父亲的年龄是儿子的 3 倍？',
  tags:['年龄问题','差不变'],
  independentSay:['他抓住了“年龄差不变”，这是这类题的关键。','可以追问他：几年前父亲是儿子的 5 倍？'],
  steps:[
    {q:'这道题在问什么？', dim:'reading', probe:'读懂问题',
     expect:{label:'几年后', keys:['几年后','多少年后','过几年']},
     confuse:[{label:'求年龄', keys:['多少岁','几岁','父亲多大'], reply:'“{hit}”不是问题。题目问的是<b>几年后</b>。'}],
     idk:'看最后一句：几年后，父亲是儿子的 3 倍？',
     off:'“{hit}”不是问题。问的是“几年后”。',
     retry:'最后问的是“几年后”。',
     hint:'问的是时间，不是年龄。',
     l4:'我给你半步：要求的是过了几年。',
     tag:'审题', say:['他把“几年后”读成了“几岁”。','可以让他圈出“几年后”。']},

    {q:'父亲和儿子的年龄差是多少？', dim:'calc', probe:'求年龄差',
     expect:{label:'28 岁', keys:['28']},
     confuse:[{label:'算成倍数', keys:['3','40','12'], reply:'“{hit}”不是年龄差。用父亲的年龄减去儿子的。'}],
     idk:'40 − 12 = ？',
     off:'“{hit}”不对。先算 40 − 12。',
     retry:'40 − 12，你算算。',
     hint:'父亲比儿子大多少岁？',
     l4:'我给你半步：40 − 12 = 28 岁。',
     tag:'计算', say:['减法算错了。','可以让他用 12 + 28 验算回 40。']},

    {q:'这个年龄差，过几年会变吗？', dim:'relation', probe:'差不变',
     expect:{label:'不变', keys:['不变','一样','不会变','相同']},
     confuse:[{label:'认为会变大', keys:['变大','变多','越来越大'], reply:'“{hit}”是错觉：两个人每年都长 1 岁，差就一直是 28。'}],
     idk:'两个人同时长一岁，差会变吗？',
     off:'“{hit}”再想想：两人每年都长 1 岁。',
     retry:'两人同时长一岁，年龄差会变吗？',
     hint:'你长一岁，爸爸也长一岁。',
     l4:'我给你半步：年龄差永远是 28 岁。',
     tag:'关系', say:['他以为年龄差会随年龄变大。','可以举例：今年差 28，明年还是差 28。']},

    {q:'当父亲是儿子的 3 倍时，年龄差相当于儿子的几倍？', dim:'model', probe:'倍数关系建模',
     expect:{label:'2 倍', keys:['2倍','两倍','二倍']},
     confuse:[{label:'算成 3 倍', keys:['3倍','三倍'], reply:'“{hit}”再想想：父亲 3 份，儿子 1 份，差是 <b>3 − 1 = 2</b> 份。'}],
     idk:'父亲是 3 份，儿子是 1 份，差是几份？',
     off:'“{hit}”还不对。画三条和一条，比较差。',
     retry:'父亲 3 份、儿子 1 份，差是 2 份。',
     hint:'倍数关系里，差 = 3 份 − 1 份。',
     l4:'我给你半步：年龄差相当于儿子的 2 倍。',
     tag:'建模', say:['他把倍数和差混为一谈。','可以让他画线段图：3 段和 1 段。']},

    {q:'差是 28 岁，相当于儿子的 2 倍。那时儿子几岁？', dim:'calc', probe:'求那时年龄',
     expect:{label:'14 岁', keys:['14']},
     confuse:[{label:'除错了', keys:['28','7','9'], reply:'“{hit}”不对。28 是儿子的 2 倍，儿子就是 28 ÷ 2。'}],
     idk:'28 是儿子的 2 倍，儿子是多少？',
     off:'“{hit}”还不是年龄。28 ÷ 2。',
     retry:'28 ÷ 2，你算算。',
     hint:'2 个儿子的年龄是 28。',
     l4:'我给你半步：28 ÷ 2 = 14 岁。',
     tag:'计算', say:['倍数关系清楚了，最后一步除错。','可以让他用 14×2 验算。']},

    {q:'儿子现在 12 岁，那时 14 岁。所以是几年后？', dim:'transfer', probe:'回到时间轴',
     expect:{label:'2 年后', keys:['2年','两年','2年后']},
     confuse:[{label:'答成年龄', keys:['14','12'], reply:'“{hit}”是年龄，不是年数。14 − 12 才是过了几年。'}],
     idk:'从 12 岁到 14 岁，过了几年？',
     off:'“{hit}”还不是年数。14 − 12。',
     retry:'14 − 12，你算算。',
     hint:'现在是 12 岁，那时是 14 岁。',
     l4:'我给你半步：14 − 12 = 2 年。',
     tag:'迁移', say:['他求出了年龄，但没转回“几年”。','可以问他：从 12 岁到 14 岁要走几年？']}
  ]
});
